DELETE FROM Promociones;
IF EXISTS (SELECT 1 FROM sys.identity_columns WHERE object_id = OBJECT_ID('Promociones') AND last_value IS NOT NULL) DBCC CHECKIDENT ('Promociones', RESEED, 0) WITH NO_INFOMSGS;
DELETE FROM Repartidores;
IF EXISTS (SELECT 1 FROM sys.identity_columns WHERE object_id = OBJECT_ID('Repartidores') AND last_value IS NOT NULL) DBCC CHECKIDENT ('Repartidores', RESEED, 0) WITH NO_INFOMSGS;
DELETE FROM Empleados;
