DELETE FROM Mesas;
IF EXISTS (SELECT 1 FROM sys.identity_columns WHERE object_id = OBJECT_ID('Mesas') AND last_value IS NOT NULL) DBCC CHECKIDENT ('Mesas', RESEED, 0) WITH NO_INFOMSGS;
DELETE FROM Clientes;
IF EXISTS (SELECT 1 FROM sys.identity_columns WHERE object_id = OBJECT_ID('Clientes') AND last_value IS NOT NULL) DBCC CHECKIDENT ('Clientes', RESEED, 0) WITH NO_INFOMSGS;
DELETE FROM Productos;
IF EXISTS (SELECT 1 FROM sys.identity_columns WHERE object_id = OBJECT_ID('Productos') AND last_value IS NOT NULL) DBCC CHECKIDENT ('Productos', RESEED, 0) WITH NO_INFOMSGS;
DELETE FROM Categorias;
IF EXISTS (SELECT 1 FROM sys.identity_columns WHERE object_id = OBJECT_ID('Categorias') AND last_value IS NOT NULL) DBCC CHECKIDENT ('Categorias', RESEED, 0) WITH NO_INFOMSGS;
DELETE FROM Proveedores;
