DELETE FROM MetodosPago;
IF EXISTS (SELECT 1 FROM sys.identity_columns WHERE object_id = OBJECT_ID('MetodosPago') AND last_value IS NOT NULL) DBCC CHECKIDENT ('MetodosPago', RESEED, 0) WITH NO_INFOMSGS;
DELETE FROM Cargos;
