IF (SELECT MIN(id_cliente) FROM Clientes) <> 1 OR (SELECT MAX(id_cliente) FROM Clientes) <> 1800
   OR (SELECT MIN(id_empleado) FROM Empleados) <> 1 OR (SELECT MAX(id_empleado) FROM Empleados) <> 31
   OR (SELECT MIN(id_repartidor) FROM Repartidores) <> 1 OR (SELECT MIN(id_mesa) FROM Mesas) <> 1
   OR (SELECT MIN(id_sucursal) FROM Sucursal) <> 1
BEGIN
    RAISERROR('Los IDENTITY no iniciaron en 1. Revise el DDL (IDENTITY(1,1)) y vuelva a ejecutar.', 16, 1);
    SET NOEXEC ON;
END
