/* ---------- 6. VALIDACIONES (todas las "debe devolver 0 filas" deben salir vacias) ---------- */
SET NOEXEC OFF;
GO
SELECT 'KPI ventas por mes' AS control, YEAR(fecha_pedido) AS anio, MONTH(fecha_pedido) AS mes, COUNT(*) AS pedidos, CAST(SUM(total) AS DECIMAL(12,2)) AS ventas
FROM Pedidos GROUP BY YEAR(fecha_pedido), MONTH(fecha_pedido) ORDER BY anio, mes;

SELECT 'KPI resultado por sede' AS control, s.nombre_sucursal,
       CAST(v.ventas AS DECIMAL(12,2)) AS ventas, CAST(ISNULL(c.compras,0) AS DECIMAL(12,2)) AS compras,
       CAST(ISNULL(g.gastos,0) AS DECIMAL(12,2)) AS gastos, CAST(v.ventas - ISNULL(c.compras,0) - ISNULL(g.gastos,0) AS DECIMAL(12,2)) AS utilidad
FROM Sucursal s
JOIN (SELECT id_sucursal, SUM(total) AS ventas FROM Pedidos GROUP BY id_sucursal) v ON v.id_sucursal = s.id_sucursal
LEFT JOIN (SELECT e.id_sucursal, SUM(c.total) AS compras FROM Compras c JOIN Empleados e ON e.id_empleado = c.id_empleado GROUP BY e.id_sucursal) c ON c.id_sucursal = s.id_sucursal
LEFT JOIN (SELECT id_sucursal, SUM(monto) AS gastos FROM Gastos GROUP BY id_sucursal) g ON g.id_sucursal = s.id_sucursal
ORDER BY s.id_sucursal;

SELECT 'Pedido vs detalle (0 filas)' AS control, p.id_pedido, p.total, SUM(d.subtotal) AS total_detalle
FROM Pedidos p JOIN DetallePedido d ON d.id_pedido = p.id_pedido GROUP BY p.id_pedido, p.total HAVING p.total <> SUM(d.subtotal);

SELECT 'Pedido sin detalle (0 filas)' AS control, p.id_pedido FROM Pedidos p LEFT JOIN DetallePedido d ON d.id_pedido = p.id_pedido WHERE d.id_pedido IS NULL;

SELECT 'Comprobante vs pedido (0 filas)' AS control, p.id_pedido FROM Pedidos p LEFT JOIN Comprobantes c ON c.id_pedido = p.id_pedido WHERE c.id_pedido IS NULL OR c.total <> p.total OR c.fecha_emision <> p.fecha_pedido;

SELECT 'Compra vs detalle (0 filas)' AS control, c.id_compra, c.total, SUM(d.subtotal) AS total_detalle
FROM Compras c JOIN DetalleCompra d ON d.id_compra = c.id_compra GROUP BY c.id_compra, c.total HAVING c.total <> SUM(d.subtotal);

SELECT 'Delivery inconsistente (0 filas)' AS control, p.id_pedido
FROM Pedidos p LEFT JOIN Delivery d ON d.id_pedido = p.id_pedido
WHERE (p.tipo_pedido = 'DELIVERY' AND d.id_pedido IS NULL) OR (p.tipo_pedido <> 'DELIVERY' AND d.id_pedido IS NOT NULL);

SELECT 'Entrega antes del pedido o mas de 90 min (0 filas)' AS control, d.id_pedido
FROM Delivery d JOIN Pedidos p ON p.id_pedido = d.id_pedido
WHERE d.hora_entrega <= p.hora_pedido OR DATEDIFF(MINUTE, p.hora_pedido, d.hora_entrega) > 90 OR d.fecha_entrega <> p.fecha_pedido;

SELECT 'Empleado de otra sede o cargo no vendedor (0 filas)' AS control, p.id_pedido
FROM Pedidos p JOIN Empleados e ON e.id_empleado = p.id_empleado
WHERE e.id_sucursal <> p.id_sucursal OR (p.tipo_pedido = 'LOCAL' AND e.id_cargo <> 4) OR (p.tipo_pedido <> 'LOCAL' AND e.id_cargo <> 2);

SELECT 'Mesa de otra sede o mesa en no-LOCAL (0 filas)' AS control, p.id_pedido
FROM Pedidos p LEFT JOIN Mesas m ON m.id_mesa = p.id_mesa
WHERE (p.tipo_pedido = 'LOCAL' AND (m.id_mesa IS NULL OR m.id_sucursal <> p.id_sucursal)) OR (p.tipo_pedido <> 'LOCAL' AND p.id_mesa IS NOT NULL);

SELECT 'Repartidor de otra sede (0 filas)' AS control, d.id_pedido
FROM Delivery d JOIN Pedidos p ON p.id_pedido = d.id_pedido
JOIN Repartidores r ON r.id_repartidor = d.id_repartidor JOIN Empleados e ON e.dni = r.dni
WHERE e.id_sucursal <> p.id_sucursal;

SELECT 'Gasto con empleado de otra sede (0 filas)' AS control, g.fecha_gasto, g.descripcion, g.id_sucursal FROM Gastos g JOIN Empleados e ON e.id_empleado = g.id_empleado WHERE e.id_sucursal <> g.id_sucursal;

SELECT 'Promo 2 fuera de martes o pollo entero sin promo en martes (0 filas)' AS control, d.id_pedido
FROM DetallePedido d JOIN Pedidos p ON p.id_pedido = d.id_pedido
WHERE (d.id_promocion = 2 AND DATEDIFF(DAY, '19000101', p.fecha_pedido) % 7 <> 1)
   OR (d.id_producto = 4 AND DATEDIFF(DAY, '19000101', p.fecha_pedido) % 7 = 1 AND d.id_promocion IS NULL);

SELECT 'Promo mal asignada (0 filas)' AS control, d.id_pedido FROM DetallePedido d
WHERE (d.id_promocion = 1 AND d.id_producto NOT IN (3, 7)) OR (d.id_promocion = 2 AND d.id_producto <> 4)
   OR (d.id_promocion IS NOT NULL AND d.precio_unitario >= (SELECT precio FROM Productos WHERE id_producto = d.id_producto));

SELECT 'Stock negativo (0 filas)' AS control, id_producto, fecha_movimiento, saldo FROM (
  SELECT id_producto, fecha_movimiento,
         SUM(CASE WHEN tipo_movimiento = 'ENTRADA' THEN cantidad ELSE -cantidad END)
         OVER (PARTITION BY id_producto ORDER BY fecha_movimiento, CASE WHEN tipo_movimiento = 'ENTRADA' THEN 0 ELSE 1 END ROWS UNBOUNDED PRECEDING) AS saldo
  FROM Inventario) x WHERE saldo < 0;

SELECT 'Reserva mayor a capacidad o sin pedido LOCAL (0 filas)' AS control, r.fecha_reserva, r.hora_reserva, r.id_cliente, r.id_mesa
FROM Reservas r JOIN Mesas m ON m.id_mesa = r.id_mesa
LEFT JOIN Pedidos p ON p.id_cliente = r.id_cliente AND p.id_mesa = r.id_mesa AND p.fecha_pedido = r.fecha_reserva AND p.tipo_pedido = 'LOCAL'
GROUP BY r.fecha_reserva, r.hora_reserva, r.id_cliente, r.id_mesa, r.cantidad_personas, m.capacidad HAVING r.cantidad_personas > m.capacidad OR COUNT(p.id_pedido) = 0;

SELECT 'Pedido, reserva o entrega fuera de 17:00-23:59 (0 filas)' AS control, 'Pedidos' AS tabla, COUNT(*) AS filas FROM Pedidos WHERE hora_pedido < '17:00:00' HAVING COUNT(*) > 0
UNION ALL SELECT 'Fuera de horario', 'Reservas', COUNT(*) FROM Reservas WHERE hora_reserva < '17:00:00' HAVING COUNT(*) > 0
UNION ALL SELECT 'Fuera de horario', 'Delivery', COUNT(*) FROM Delivery WHERE hora_entrega < '17:00:00' HAVING COUNT(*) > 0;

SELECT 'Fechas fuera de 2026-04-01..2026-09-30 (0 filas)' AS control, 'Pedidos' AS tabla, COUNT(*) AS filas FROM Pedidos WHERE fecha_pedido NOT BETWEEN '2026-04-01' AND '2026-09-30' HAVING COUNT(*) > 0
UNION ALL SELECT 'Fechas fuera de rango', 'Compras', COUNT(*) FROM Compras WHERE fecha_compra NOT BETWEEN '2026-04-01' AND '2026-09-30' HAVING COUNT(*) > 0
UNION ALL SELECT 'Fechas fuera de rango', 'Gastos', COUNT(*) FROM Gastos WHERE fecha_gasto NOT BETWEEN '2026-04-01' AND '2026-09-30' HAVING COUNT(*) > 0
UNION ALL SELECT 'Fechas fuera de rango', 'Inventario', COUNT(*) FROM Inventario WHERE fecha_movimiento NOT BETWEEN '2026-04-01' AND '2026-09-30' HAVING COUNT(*) > 0;
GO
